{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C51"],
      "claim": "A close structural analogue with a tolyl urea motif had human oral bioavailability of 0.7857, supporting high F for the query's related tolyl/sulfonylurea scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C43"],
      "claim": "Tolbutamide, a sulfonylurea, has absolute human oral bioavailability of 80–90%, directly supporting high F for the query's sulfonylurea core.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Recainam, a tolyl urea with an isopropylamine side chain, showed 73% absolute oral bioavailability in healthy men, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Lumiracoxib, a diarylamine analogue, showed 74% absolute oral bioavailability in healthy subjects, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Pimasertib, a pyridine-aniline analogue, showed 73% absolute oral bioavailability in patients, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Lisofylline had only 5.9% oral bioavailability in humans, a low-F outlier, but its low similarity and different scaffold limit transferability to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Multiple transferable experimental analogues with tolyl urea, sulfonylurea, diarylamine, and pyridine-aniline features show high absolute oral bioavailability (64–90%), outweighing one low-F outlier; predict high.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability value is available for the query molecule.",
    "Morgan similarities to evidence molecules are low (0.22–0.35), limiting structural transferability.",
    "Conflicting bupropion bioavailability records (10% vs 90%) introduce uncertainty for that analogue family.",
    "The single low-F outlier (lisofylline, 5.9%) has limited structural resemblance to the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

